293	    /**
294	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
295	     * contained in the owner's {@link #customerCode}.
296	     */
297	    public int getCheckDigit() {
298	        return luhnCheckDigit(this.customerCode);
299	    }
300	
301	    /**
302	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
303	     * contained in {@code value}. Reading the digits right to left, every second one is
304	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
305	     * digits are summed, and the check digit is the amount that must be added to that sum to
306	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
307	     * the digit is taken over exactly the digits the string carries.
308	     */
309	    private static int luhnCheckDigit(String value) {
310	        int sum = 0;
311	        boolean doubling = true;
312	        for (int i = value.length() - 1; i >= 0; i--) {
313	            char c = value.charAt(i);
314	            if (c < '0' || c > '9') {
315	                continue;
316	            }
317	            int digit = c - '0';
318	            if (doubling) {
319	                digit *= 2;
320	                if (digit > 9) {
321	                    digit -= 9;
322	                }
323	            }
324	            sum += digit;
325	            doubling = !doubling;
326	        }
327	        return (10 - (sum % 10)) % 10;
328	    }
