365	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
366	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
367	        "NSW", "Australia/Sydney",
368	        "VIC", "Australia/Melbourne",
369	        "QLD", "Australia/Brisbane");
370	
371	    /**
372	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
373	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
374	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
375	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
376	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
377	     */
378	    public String getTimezone() {
379	        return REGION_TIMEZONE.get(getLocality());
380	    }
