382	    /**
383	     * The region derived from this owner's postcode alone: the region whose fixed
384	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
385	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
386	     * component built into the owner's customer code at creation and, through it, the source of the
387	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
388	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
389	     */
390	    public String getRegion() {
391	        return regionOfPostcode(this.postcode);
392	    }
393	
394	    /**
395	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
396	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
397	     * no known range.
398	     */
399	    private static String regionOfPostcode(String postcode) {
400	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
401	            return null;
402	        }
403	        int value = Integer.parseInt(postcode);
404	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
405	            int[] range = entry.getValue();
406	            if (value >= range[0] && value <= range[1]) {
407	                return entry.getKey();
408	            }
409	        }
410	        return null;
411	    }
412	
413	    /**
414	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
415	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
416	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
417	     */
418	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
419	        "NSW", new int[] {2000, 2099},
420	        "VIC", new int[] {3000, 3099},
421	        "QLD", new int[] {4000, 4099});
422	
423	    /**
424	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
425	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
426	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
427	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
428	     * city with no known region accepts any 4-digit postcode.
429	     */
430	    public boolean isPostcodeValid() {
431	        if (this.postcode == null) {
432	            return true;
433	        }
434	        if (!this.postcode.matches("[0-9]{4}")) {
435	            return false;
436	        }
437	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
438	        if (range == null) {
439	            return true;
440	        }
441	        int value = Integer.parseInt(this.postcode);
442	        return value >= range[0] && value <= range[1];
443	    }
444	
445	    /**
446	     * The national (subscriber) digit count required by each known country calling code, keyed by
447	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
448	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
449	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
450	     * re-derived elsewhere.
451	     */
452	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
453	        "1", 10,
454	        "61", 9);
455	
456	    /**
457	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
458	     * E.164 digit string, choosing the longest matching code known to
459	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
460	     * country code. This is the single place a country code is read from an E.164 number, so every
461	     * rule keyed by that code shares one derivation.
462	     */
463	    private static String countryCodeOf(String e164Digits) {
464	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
465	            .filter(e164Digits::startsWith)
466	            .max(Comparator.comparingInt(String::length))
467	            .orElse(null);
468	    }
469	
470	    /**
471	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
472	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
473	     * known code wins; a number whose country code is not recognised passes this check (its length is
474	     * then governed only by the general E.164 bound), while a recognised code must be followed by
475	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
476	     */
477	    public static boolean hasValidNationalLength(String e164Digits) {
478	        String countryCode = countryCodeOf(e164Digits);
479	        if (countryCode == null) {
480	            return true;
481	        }
482	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
483	    }
484	
485	    /**
486	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
487	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
488	     * gain 3 when the owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. The email,
489	     * namesake and household factors are available on creation; the tenure factor is reached only
490	     * once tenure grows beyond 365 days.
491	     */
492	    public Integer getMembershipPoints() {
493	        int points = 0;
494	        if (hasEmail()) {
495	            points += 2;
496	        }
497	        if (hasNoNamesakes()) {
498	            points += 1;
499	        }
500	        if (hasLargeHousehold()) {
501	            points += 2;
502	        }
503	        if (hasTenureBeyondOneYear()) {
504	            points += 3;
505	        }
506	        return points;
507	    }
508	
509	    /**
510	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
511	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
512	     * more.
513	     */
514	    public Integer getMembershipLevel() {
515	        int points = getMembershipPoints();
516	        if (points >= 6) {
517	            return 4;
518	        }
519	        if (points >= 4) {
520	            return 3;
521	        }
522	        if (points >= 2) {
523	            return 2;
524	        }
525	        return 1;
526	    }
527	
528	    /**
529	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
530	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
531	     * known, is treated as not a large household.
532	     */
533	    private boolean hasLargeHousehold() {
534	        return this.householdSize != null && this.householdSize >= 3;
535	    }
536	
537	    /**
538	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
539	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
540	     * email presence so the check is never re-derived elsewhere.
541	     */
542	    private boolean hasEmail() {
543	        return this.email != null && !this.email.isEmpty();
544	    }
545	
546	    /**
547	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
548	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
549	     * not known, is treated as not unique.
550	     */
551	    private boolean hasNoNamesakes() {
552	        return this.namesakeCount != null && this.namesakeCount == 0;
553	    }
554	
555	    /**
556	     * Whether this owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. A newly created owner
557	     * (zero tenure) does not qualify; the threshold is crossed only once tenure grows beyond one year.
558	     */
559	    private boolean hasTenureBeyondOneYear() {
560	        return this.getTenureDays() > 365;
561	    }
562	
563	    /**
564	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
565	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
566	     * zero tenure). Never negative.
567	     */
568	    public long getTenureDays() {
569	        if (this.registrationDate == null) {
570	            return 0;
571	        }
572	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
573	    }
