625	    protected Set<Pet> getPetsInternal() {
626	        if (this.pets == null) {
627	            this.pets = new HashSet<>();
628	        }
629	        return this.pets;
630	    }
631	
632	    protected void setPetsInternal(Set<Pet> pets) {
633	        this.pets = pets;
634	    }
635	
636	    public List<Pet> getPets() {
637	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
638	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
639	        return Collections.unmodifiableList(sortedPets);
640	    }
641	
642	    public void setPets(List<Pet> pets) {
643	        this.pets = new HashSet<>(pets);
644	    }
645	
646	    public void addPet(Pet pet) {
647	        getPetsInternal().add(pet);
648	        pet.setOwner(this);
649	    }
650	
651	    /**
652	     * Return the Pet with the given name, or null if none found for this Owner.
653	     *
654	     * @param name to test
655	     * @return true if pet name is already in use
656	     */
657	    public Pet getPet(String name) {
