659	    }
660	
661	    /**
662	     * Return the Pet with the given name, or null if none found for this Owner.
663	     *
664	     * @param name to test
665	     * @return true if pet name is already in use
666	     */
667	    public Pet getPet(String name, boolean ignoreNew) {
668	        name = name.toLowerCase();
669	        for (Pet pet : getPetsInternal()) {
670	            if (!ignoreNew || !pet.isNew()) {
671	                String compName = pet.getName();
672	                compName = compName.toLowerCase();
673	                if (compName.equals(name)) {
674	                    return pet;
675	                }
676	            }
677	        }
