17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Objects;
28	import java.util.Set;
29	import java.util.stream.Collectors;
30	
31	import org.slf4j.Logger;
32	import org.slf4j.LoggerFactory;
33	import org.springframework.http.HttpHeaders;
34	import org.springframework.http.HttpStatus;
35	import org.springframework.http.ResponseEntity;
36	import org.springframework.samples.petclinic.mapper.OwnerMapper;
37	import org.springframework.samples.petclinic.mapper.PetMapper;
38	import org.springframework.samples.petclinic.mapper.VisitMapper;
39	import org.springframework.samples.petclinic.model.Owner;
40	import org.springframework.samples.petclinic.model.Pet;
41	import org.springframework.samples.petclinic.model.Visit;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    private final AddressNormalizer addressNormalizer;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper,
83	                                 AddressNormalizer addressNormalizer) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.addressNormalizer = addressNormalizer;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	
121	        HttpStatus invalid = normalizeAndValidate(owner);
122	        if (invalid != null) {
123	            return new ResponseEntity<>(invalid);
124	        }
125	        if (isDailyLimitReached(owner.getRegistrationDate())) {
126	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
127	        }
128	
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        assignHousehold(owner);
131	
132	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
133	        if (conflict != null) {
134	            return new ResponseEntity<>(conflict);
135	        }
136	
137	        assignDerivedAttributes(owner, sharesHousehold);
138	        this.clinicService.saveOwner(owner);
139	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
140	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
141	            owner.getMembershipLevel(), owner.getMembershipNumber());
142	        return created(owner);
143	    }
144	
145	    /**
146	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
147	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
148	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
149	     * postcode is checked against its city's region, a registration date in the future is rejected,
150	     * and the effective registration date (the supplied one, or today when none was given) is rolled
151	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
152	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
153	     * otherwise.
154	     */
155	    private HttpStatus normalizeAndValidate(Owner owner) {
156	        if (!normalizeAddress(owner)) {
157	            return HttpStatus.BAD_REQUEST;
158	        }
159	        String telephone = toE164(owner.getTelephone());
160	        if (telephone == null) {
161	            return HttpStatus.BAD_REQUEST;
162	        }
163	        owner.setTelephone(telephone);
164	        if (isDisposableEmail(owner.getEmail())) {
165	            return HttpStatus.BAD_REQUEST;
166	        }
167	        if (!owner.isPostcodeValid()) {
168	            return HttpStatus.BAD_REQUEST;
169	        }
170	        if (owner.getRegistrationDate() != null
171	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
172	            return HttpStatus.BAD_REQUEST;
173	        }
174	        LocalDate effectiveDate = owner.getRegistrationDate() != null
175	            ? owner.getRegistrationDate() : LocalDate.now();
176	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
177	        return null;
178	    }
179	
180	    /**
181	     * Normalize the owner's supplied address into its canonical stored form and report whether an
182	     * address was supplied at all. The owner may supply its address either as the structured
183	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
184	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
185	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
186	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
187	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
188	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
189	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
190	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
191	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
192	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
193	     * create must be rejected with {@code 400 Bad Request}.
194	     */
195	    private boolean normalizeAddress(Owner owner) {
196	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
197	        if (!line1.isEmpty()) {
198	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
199	            owner.setAddressLine1(line1);
200	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
201	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
202	            return true;
203	        }
204	        String address = addressNormalizer.normalize(owner.getAddress());
205	        if (address.isEmpty()) {
206	            return false;
207	        }
208	        owner.setAddressLine1(null);
209	        owner.setAddressLine2(null);
210	        owner.setAddress(address);
211	        return true;
212	    }
213	
214	    /**
215	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
216	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
217	     */
218	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
219	        "mailinator.com", "tempmail.com", "guerrillamail.com");
220	
221	    /**
222	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
223	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
224	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
225	     * against the blocklist.
226	     */
227	    private boolean isDisposableEmail(String email) {
228	        if (email == null || email.isEmpty()) {
229	            return false;
230	        }
231	        int at = email.lastIndexOf('@');
232	        if (at < 0) {
233	            return false;
234	        }
235	        String domain = email.substring(at + 1).toLowerCase();
236	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
237	    }
238	
239	    /**
240	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
241	     * deterministically from the owner's lastName and postcode, so every owner sharing that
242	     * lastName and postcode is assigned the same value automatically, independent of whether the
243	     * owner declares it shares a household. The link is assigned before the
244	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
245	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
246	     * size}.
247	     */
248	    private void assignHousehold(Owner owner) {
249	        owner.setHouseholdId(householdId(owner));
250	    }
251	
252	    /**
253	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
254	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
255	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
256	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
257	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
258	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
259	     * when the owner clashes with nothing and may be created.
260	     */
261	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
262	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
263	            return HttpStatus.CONFLICT;
264	        }
265	        if (isCityAtCapacity(owner.getCity())) {
266	            return HttpStatus.CONFLICT;
267	        }
268	        return null;
269	    }
270	
271	    /**
272	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
273	     * {@code Location} header pointing at {@code /api/owners/{id}}.
274	     */
275	    private ResponseEntity<OwnerDto> created(Owner owner) {
276	        HttpHeaders headers = new HttpHeaders();
277	        headers.setLocation(UriComponentsBuilder.newInstance()
278	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
279	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
280	    }
281	
282	    /**
283	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
284	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
285	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
286	     * householdSize}. Each is computed from the owner's own fields together with the owners already
287	     * present, so this runs after the owner has been validated and has passed the duplicate and
288	     * capacity checks, and immediately before it is persisted.
289	     */
290	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
291	        owner.setCustomerCode(customerCode(owner));
292	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
293	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
294	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
295	        assignPossibleDuplicate(owner, sharesHousehold);
296	    }
297	
298	    /**
299	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
300	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
301	     * so it is never flagged. Otherwise, because this runs after the hard
302	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
303	     * match; it is flagged only when it is a soft match of an existing owner as determined by
304	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
305	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
306	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
307	     */
308	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
309	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
310	        owner.setPossibleDuplicate(match != null);
311	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
312	    }
313	
314	    /**
315	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
316	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
317	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
318	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
319	     * postcode never matches.
320	     */
321	    private Owner findSoftDuplicate(Owner owner) {
322	        if (owner.getPostcode() == null) {
323	            return null;
324	        }
325	        String candidateLastName = normalizeName(owner.getLastName());
326	        return this.clinicService.findAllOwners().stream()
327	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
328	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
329	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
330	            .min(Comparator.comparingInt(Owner::getId))
331	            .orElse(null);
332	    }
333	
334	    /**
335	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
336	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
337	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
338	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
339	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
340	     * every value built from the customer code (the membership number and its check digit) and the
341	     * owner's locality are derived from it.
342	     *
343	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
344	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
345	     * unique, and the de-duplicated code is returned.
346	     */
347	    private String customerCode(Owner owner) {
348	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
349	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
350	        String base = region + "-" + hash8;
351	
352	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
353	            .map(Owner::getCustomerCode)
354	            .filter(Objects::nonNull)
355	            .collect(Collectors.toSet());
356	
357	        if (!existingCodes.contains(base)) {
358	            return base;
359	        }
360	        int n = 2;
361	        while (existingCodes.contains(base + "-" + n)) {
362	            n++;
363	        }
364	        return base + "-" + n;
365	    }
366	
367	    /**
368	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
369	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
370	     * (business-day) registration date of the owner being created, so owners are counted per
371	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
372	     */
373	    private boolean isDailyLimitReached(LocalDate day) {
374	        long count = this.clinicService.findAllOwners().stream()
375	            .filter(existing -> day.equals(existing.getRegistrationDate()))
376	            .count();
377	        return count >= 100;
378	    }
379	
380	    /**
381	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
382	     * more than 80 owners have already been created for the given business day. Counts the owners
383	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
384	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
385	     * warning.
386	     */
387	    private boolean isBulkSignup(LocalDate day) {
388	        long count = this.clinicService.findAllOwners().stream()
389	            .filter(existing -> day.equals(existing.getRegistrationDate()))
390	            .count();
391	        return count > 80;
392	    }
393	
394	    /**
395	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
396	     * advance it to the following Monday; a weekday is returned unchanged.
397	     */
398	    private LocalDate toBusinessDay(LocalDate date) {
399	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
400	            date = date.plusDays(1);
401	        }
402	        return date;
403	    }
404	
405	    /**
406	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
407	     * more owners. Cities are compared case-insensitively.
408	     */
409	    private boolean isCityAtCapacity(String city) {
410	        long count = this.clinicService.findAllOwners().stream()
411	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
412	            .count();
413	        return count >= 50;
414	    }
415	
416	    /**
417	     * The number of existing owners that already share the given firstName and lastName,
418	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
419	     * whitespace runs collapsed). Counted over the owners present before this create.
420	     */
421	    private int namesakeCount(String firstName, String lastName) {
422	        String candidateFirstName = normalizeName(firstName);
423	        String candidateLastName = normalizeName(lastName);
424	        return (int) this.clinicService.findAllOwners().stream()
425	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
426	                && normalizeName(existing.getLastName()).equals(candidateLastName))
427	            .count();
428	    }
429	
430	    /**
431	     * The number of members in this owner's household after this create: the count of existing
432	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
433	     * created. An owner with no household ({@code householdId == null}) is a household of one.
434	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
435	     * does not depend on the order in which household members were created.
436	     */
437	    private int householdSize(String householdId) {
438	        if (householdId == null) {
439	            return 1;
440	        }
441	        long existing = this.clinicService.findAllOwners().stream()
442	            .filter(other -> householdId.equals(other.getHouseholdId()))
443	            .count();
444	        return (int) existing + 1;
445	    }
446	
447	    /**
448	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
449	     * cannot form a valid E.164 number.
450	     *
451	     * <p>A leading '+' and country code are kept when present; otherwise country code
452	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
453	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
454	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
455	     * exactly the national-digit count that code requires (see
456	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
457	     */
458	    private String toE164(String telephone) {
459	        if (telephone == null) {
460	            return null;
461	        }
462	        boolean hasCountryCode = telephone.trim().startsWith("+");
463	        String digits = telephone.replaceAll("\\D", "");
464	        String e164;
465	        if (hasCountryCode) {
466	            e164 = digits;
467	        } else {
468	            if (digits.startsWith("0")) {
469	                digits = digits.substring(1);
470	            }
471	            e164 = "61" + digits;
472	        }
473	        if (e164.length() < 8 || e164.length() > 15) {
474	            return null;
475	        }
476	        if (!Owner.hasValidNationalLength(e164)) {
477	            return null;
478	        }
479	        return "+" + e164;
480	    }
481	
482	    /**
483	     * Whether the candidate owner belongs to a household that already exists, and so must be
484	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
485	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
486	     * and postcode), so any existing owner carrying the same householdId means this owner is a
487	     * second member of an already-registered household. Two owners sharing a lastName and postcode
488	     * are therefore the same household: the second is a household duplicate.
489	     */
490	    private boolean isHouseholdDuplicate(Owner owner) {
491	        String householdId = owner.getHouseholdId();
492	        if (householdId == null) {
493	            return false;
494	        }
495	        return this.clinicService.findAllOwners().stream()
496	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
497	    }
498	
499	    /**
500	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
501	     * to a single space and lower-case. A null value normalizes to the empty string.
502	     */
503	    private String normalizeName(String value) {
504	        if (value == null) {
505	            return "";
506	        }
507	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
508	    }
509	
510	    /**
511	     * A stable shared identifier for the household an owner belongs to, derived deterministically
512	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
513	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
514	     * assigned the same value regardless of the order in which they are created. Formatted as the
515	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
516	     * (an absent postcode contributes the empty string).
517	     */
518	    private String householdId(Owner owner) {
519	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
520	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
521	        return shaHexUpper(key).substring(0, 12);
522	    }
523	
524	    /**
525	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
526	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
527	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
528	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
529	     * {@link #customerCode} keeps the first 8).
530	     */
531	    private String shaHexUpper(String input) {
532	        try {
533	            byte[] digest = MessageDigest.getInstance("SHA-256")
534	                .digest(input.getBytes(StandardCharsets.UTF_8));
535	            StringBuilder sb = new StringBuilder(digest.length * 2);
536	            for (byte b : digest) {
537	                sb.append(String.format("%02x", b));
538	            }
539	            return sb.toString().toUpperCase();
540	        }
541	        catch (NoSuchAlgorithmException e) {
542	            throw new IllegalStateException("SHA-256 not available", e);
543	        }
544	    }
545	
546	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
547	    @Override
548	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
549	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
550	        if (currentOwner == null) {
551	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
552	        }
553	        currentOwner.setAddress(ownerFieldsDto.getAddress());
554	        currentOwner.setCity(ownerFieldsDto.getCity());
555	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
556	        currentOwner.setLastName(ownerFieldsDto.getLastName());
557	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
558	        this.clinicService.saveOwner(currentOwner);
559	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
560	    }
561	
562	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
563	    @Transactional
564	    @Override
565	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
566	        Owner owner = this.clinicService.findOwnerById(ownerId);
567	        if (owner == null) {
568	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
569	        }
570	        this.clinicService.deleteOwner(owner);
571	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
572	    }
573	
574	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
575	    @Override
576	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
577	        Owner owner = this.clinicService.findOwnerById(ownerId);
578	        if (owner == null) {
579	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
580	        }
581	        HttpHeaders headers = new HttpHeaders();
582	        Pet pet = petMapper.toPet(petFieldsDto);
583	        owner.setId(ownerId);
584	        pet.setOwner(owner);
585	        pet.getType().setName(null);
586	        this.clinicService.savePet(pet);
587	        PetDto petDto = petMapper.toPetDto(pet);
588	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
589	            .buildAndExpand(pet.getId()).toUri());
590	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
591	    }
592	
593	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
594	    @Override
595	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
596	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
597	        if (currentOwner != null) {
598	            Pet currentPet = this.clinicService.findPetById(petId);
599	            if (currentPet != null) {
600	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
601	                currentPet.setName(petFieldsDto.getName());
602	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
603	                this.clinicService.savePet(currentPet);
604	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
605	            }
606	        }
607	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
608	    }
609	
610	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
611	    @Override
612	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
613	        HttpHeaders headers = new HttpHeaders();
614	        Visit visit = visitMapper.toVisit(visitFieldsDto);
615	        Pet pet = new Pet();
616	        pet.setId(petId);
617	        visit.setPet(pet);
618	        this.clinicService.saveVisit(visit);
619	        VisitDto visitDto = visitMapper.toVisitDto(visit);
620	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
621	            .buildAndExpand(visit.getId()).toUri());
622	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
623	    }
624	
625	
626	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
627	    @Override
628	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
629	        Owner owner = this.clinicService.findOwnerById(ownerId);
630	        if (owner != null) {
631	            Pet pet = owner.getPet(petId);
632	            if (pet != null) {
633	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
634	            }
635	        }
636	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
637	    }
638	}
